const request = require('supertest');
const app = require('./app');

describe('POST /users – input validation', () => {
  // ── 400 cases ──────────────────────────────────────────────────────────────

  test('returns 400 when the request body is empty', async () => {
    const res = await request(app).post('/users').send({});
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/required/i);
  });

  test('returns 400 when `name` is missing (no body at all)', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send('{}');
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/required/i);
  });

  test('returns 400 when `name` is null', async () => {
    const res = await request(app).post('/users').send({ name: null });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/required/i);
  });

  test('returns 400 when `name` is a number', async () => {
    const res = await request(app).post('/users').send({ name: 42 });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/string/i);
  });

  test('returns 400 when `name` is a boolean', async () => {
    const res = await request(app).post('/users').send({ name: true });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/string/i);
  });

  test('returns 400 when `name` is an array', async () => {
    const res = await request(app).post('/users').send({ name: ['Alice'] });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/string/i);
  });

  test('returns 400 when `name` is an object', async () => {
    const res = await request(app).post('/users').send({ name: { first: 'Alice' } });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/string/i);
  });

  test('returns 400 when `name` is an empty string', async () => {
    const res = await request(app).post('/users').send({ name: '' });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/blank/i);
  });

  test('returns 400 when `name` is a whitespace-only string', async () => {
    const res = await request(app).post('/users').send({ name: '   ' });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/blank/i);
  });

  // ── 201 cases ──────────────────────────────────────────────────────────────

  test('returns 201 and the trimmed name when `name` is valid', async () => {
    const res = await request(app).post('/users').send({ name: 'Charlie' });
    expect(res.status).toBe(201);
    expect(res.body.name).toBe('Charlie');
  });

  test('trims leading/trailing whitespace from a valid `name`', async () => {
    const res = await request(app).post('/users').send({ name: '  Dana  ' });
    expect(res.status).toBe(201);
    expect(res.body.name).toBe('Dana');
  });
});

